SELECT COALESCE(SUM(so.total_amount), 0)
FROM wms_sales_out so
WHERE so.del_flag = '0'
  AND so.tenant_id = #{tenantId}
  AND so.approve_by IS NOT NULL
  AND so.approve_by != ''
  AND DATE(so.create_time) >= #{startDate}
  AND DATE(so.create_time) <= #{endDate}

      AND so.warehouse_id = #{warehouseId}

SELECT COALESCE(SUM(sr.total_amount), 0)
FROM wms_sales_return sr
WHERE sr.del_flag = '0'
  AND sr.tenant_id = #{tenantId}
  AND sr.approve_by IS NOT NULL
  AND sr.approve_by != ''
  AND DATE(sr.create_time) >= #{startDate}
  AND DATE(sr.create_time) <= #{endDate}

      AND sr.warehouse_id = #{warehouseId}

SELECT COUNT(*)
FROM wms_sales_out so
WHERE so.del_flag = '0'
  AND so.tenant_id = #{tenantId}
  AND so.approve_by IS NOT NULL
  AND so.approve_by != ''
  AND DATE(so.create_time) >= #{startDate}
  AND DATE(so.create_time) <= #{endDate}

      AND so.warehouse_id = #{warehouseId}

SELECT COALESCE(SUM(COALESCE(l.quantity, 0) * COALESCE(l.cost_price, 0)), 0)
FROM wms_stock_log l
INNER JOIN wms_sales_out so ON so.id = l.bill_id
WHERE l.bill_type = '2'
  AND l.change_type = '2'
  AND so.del_flag = '0'
  AND so.tenant_id = #{tenantId}
  AND so.approve_by IS NOT NULL
  AND so.approve_by != ''
  AND DATE(so.create_time) >= #{startDate}
  AND DATE(so.create_time) <= #{endDate}

      AND so.warehouse_id = #{warehouseId}

